using Avalonia;using Avalonia.Controls;using Avalonia.Controls.ApplicationLifetimes;using Avalonia.Markup.Xaml;using SPharmacyLog.Data;using SPharmacyLog.Core;using SPharmacyLog.UI.Views;using SPharmacyLog.UI.Services;namespace SPharmacyLog.UI;public partial class App:Application{public override void Initialize()=>AvaloniaXamlLoader.Load(this);public override async void OnFrameworkInitializationCompleted(){if(ApplicationLifetime is IClassicDesktopStyleApplicationLifetime d){try{if(!PharmacyLicenseManager.Load()){var activation=new LicenseActivationWindow();await activation.ShowDialog(d.MainWindow);if(!PharmacyLicenseManager.Result.IsValid){d.Shutdown();return;}}await using var db=new PharmacyDbContext(PharmacyDb.Options());await db.Database.MigrateAsync();d.MainWindow=new LoginWindow();}catch(Exception ex){d.MainWindow=new Window{Title="S Pharmacy Log startup error",Width=600,Height=240,Content=new TextBlock{Text=ex.Message,Margin=new Thickness(24),TextWrapping=Avalonia.Media.TextWrapping.Wrap}};}d.MainWindow?.Show();}base.OnFrameworkInitializationCompleted();}}